<?php
namespace App\Http\Controllers;
use App\Models\AssistanceRequest; use App\Models\DiningSession; use App\Models\Table; use Illuminate\Http\Request;
class SessionController extends Controller { private array $active=['Opened','Ordering','Preparing','Ready','Served','Bill Requested','Payment Pending']; public function open(Request $r,string $code){$d=$r->validate(['name'=>'nullable|string|max:100','phone'=>'nullable|string|max:30']);$t=Table::where('code',$code)->where('is_active',true)->firstOrFail();if($t->sessions()->whereIn('status',$this->active)->exists())return response()->json(['message'=>'يوجد جلسة نشطة لهذه الطاولة بالفعل'],409);$s=DiningSession::create(['restaurant_id'=>$t->restaurant_id,'table_id'=>$t->id,'name'=>$d['name']??null,'phone'=>$d['phone']??null,'status'=>'Opened']);return response()->json(['data'=>$s->load('table')],201);} public function show(int $id){return response()->json(['data'=>DiningSession::with(['table','orders.items.product'])->findOrFail($id)]);} public function assistance(int $id){$s=DiningSession::findOrFail($id);if($s->status==='Closed')return response()->json(['message'=>'الجلسة مغلقة'],409);if(!$s->assistanceRequests()->where('status','open')->exists())AssistanceRequest::create(['dining_session_id'=>$id]);return response()->json(['message'=>'تم إرسال طلب المساعدة']);} public function active(Request $r){return response()->json(['data'=>DiningSession::with('table')->where('restaurant_id',$r->user()->restaurant_id)->whereIn('status',$this->active)->latest()->get()]);}}
